public abstract class Repository<T>(
    IBlobStorageClient blobStorageClient,
    string containerName) where T : IRepositoryKey

public class BlobStorageHealthCheck(
    ILogger<BlobStorageHealthCheck> logger,
    CarConfigurationRepository carConfigurationRepository) : IHealthCheck

public class TransformationService(
    IProductMapperProvider productMapperProvider,
    IProductFullDetailsCacheService productDetailsCacheService) : ITransformationService

public record GetExternalCarCodeRequest(
    [BindRequired] string Market,
    [BindRequired] int ModelYear,
    [BindRequired] string Pno12,
    string ClientName = "",
    string LocalEditionCode = "");

public record CarConfigKey(
    string SpecMarket,
    int ModelYear,
    string Pno12
);

public record Feature(
    string Code,
    string Description,
    ProductionDates ProductionDates,
    ImmutableHashSet<string> Tags,
    string ShortDescription,
    string Family,
    string Group,
    string GroupDescription
) : IConfigItem;

public record PackageOption(
    string Code,
    string Description,
    ProductionDates ProductionDates,
    ImmutableHashSet<string> Tags,
    ImmutableList<Feature> Features,
    ImmutableList<ReplacedOption> ReplacesOptions,
    ImmutableList<ReplacedOption> ExchangeableWith
) : IConfigItem;

public record Package(
    string Code,
    string Description,
    ProductionDates ProductionDates,
    ImmutableHashSet<string> Tags,
    ImmutableList<PackageOption> OptionsInPackage,
    ImmutableList<PackageColour> ColoursInPackage,
    ImmutableList<PackageInteriorRoom> InteriorRoomsInPackage
) : IConfigItem;

public record ProductionDates(
    ProductionWeek Start,
    ProductionWeek End
);

public record ListPno12Query(
    ImmutableHashSet<string> SpecMarkets,
    ImmutableHashSet<int> ModelYears,
    ImmutableHashSet<string> CarTypes,
    int Offset,
    int Limit
);

public record InteriorRoom(
    string Code,
    string Description,
    ProductionDates ProductionDates,
    ImmutableHashSet<string> Tags,
    ImmutableList<Feature> Features
) : IConfigItem;

public record Option(
    string Code,
    string Description,
    ProductionDates ProductionDates,
    ImmutableHashSet<string> Tags,
    ImmutableList<Feature> Features,
    ImmutableList<ReplacedOption> ReplacesOptions
) : IConfigItem;

public sealed record VariantVersion(
    VariantDetail Variant,
    DateTimeOffset ValidFrom,
    DateTimeOffset? ValidTo = null,
    VersionStatus Status = VersionStatus.Active,
    string? SourceEvent = null);

public record ReplacedOption(
    string Code,
    string Description,
    ProductionDates ProductionDates,
    ImmutableHashSet<string> Tags,
    ImmutableList<Feature> Features
) : IConfigItem;

public record SpecMarket(
    string Code,
    string? LegacyGccCode,
    string Name,
    ImmutableList<Country> Countries
);

public record ListPno12QueryResult(
    ImmutableHashSet<CarConfigKey> Keys,
    bool HasMore
);

public record Pno12(
      int Skip,
      int Take,
      int Total,
      IReadOnlyCollection<Pno12ListItem> Items,
      Pno12QueryAggregation? Aggregation);

public record Colour(
    string Code,
    string Description,
    ProductionDates ProductionDates,
    ImmutableHashSet<string> Tags
) : IConfigItem;

public record PackageInteriorRoom(
    string Code,
    string Description,
    ProductionDates ProductionDates,
    ImmutableHashSet<string> Tags,
    ImmutableList<Feature> Features,
    ImmutableList<InteriorRoom> ExchangeableWith
) : IConfigItem;

public record MarketAuthEntry(FeatureType Type,
    string Code,
    string Name);

public record SMessage(
    string Code,
    string Description,
    ProductionDates ProductionDates,
    ImmutableHashSet<string> Tags
) : IConfigItem;

public record GlobalDictionaryEntry(
    FeatureType Type,
    string Code,
    string Name,
    string LongName);

public record MarketAuthEntriesInfo(string SpecMarket,
    string Pno3,
    int ModelYear,
    ImmutableList<MarketAuthEntry> Entries);

public record Country(
    string Name,
    string Alpha2Code,
    string Alpha3Code,
    int NumericCode
);

public record PackageColour(
    string Code,
    string Description,
    ProductionDates ProductionDates,
    ImmutableHashSet<string> Tags,
    ImmutableList<Colour> ExchangeableWith
) : IConfigItem;

public record GlobalDictionaryEntriesInfo(string Pno3,
    int ModelYear,
    ImmutableList<GlobalDictionaryEntry> Entries);

public record ProductionWeek(
    int StructureWeek,
    DateTime DateTime
);

public class KafkaConsumerService(
    IMessageProcessorFactory messageProcessorFactory,
    ILogger<KafkaConsumerService> logger,
    InstrumentedConsumerBuilder<string, byte[]> consumerBuilder
) : BackgroundService

public class AzureTokenHealthCheck(
    ITokenProvider tokenProvider
) : IHealthCheck

public class AzureAuthenticationDelegatingHandler(
    IConfidentialClientApplicationWrapper confidentialClientApplicationWrapper,
    string resourceId) : DelegatingHandler

public record Rule(
    RuleType Type,
    ImmutableArray<Rule> SubRules,
    string? StringValue,
    int? IntValue,
    Guid? ClassificationValueId,
    Classification? ClassificationValue
);

public record Classification(
    Guid Id,
    string SystemName,
    ClassificationType Type,
    Rule Rule,
    Brand Brand
);

public record UpstreamItem(
    Guid Id,
    ItemType Type,
    string Code,
    ImmutableArray<string> SystemNames,
    bool Archived,
    string ArchiveReason,
    bool Preliminary,
    int NumVariants
);

public record ProductVariant(
    Guid Id,
    string SystemName,
    string ProductName,
    string Key,
    ProductType Type,
    Rule Rule,
    ImmutableArray<string> PrimaryCodes,
    ImmutableArray<UpstreamItem> UpstreamItems
);

public record Product(
    Guid Id,
    string SystemName,
    ImmutableArray<ProductVariant> Variants,
    string Brand,
    ProductType Type,
    ImmutableArray<string> Codes
);

public record PsClassification(
    Guid Id,
    string? SystemName,
    PsClassificationType? Type,
    PsRule? Rule,
    PsBrand? Brand
);

public record PsProduct(
    Guid Id,
    string? SystemName,
    ImmutableArray<PsProductVariant>? Variants,
    string? Brand,
    PsProductType? Type,
    ImmutableArray<string>? Codes
);

public record PsUpstreamItem(
    Guid Id,
    PsItemType? Type,
    string? Code,
    ImmutableArray<string>? SystemNames,
    bool? Archived,
    string? ArchiveReason,
    bool? Preliminary,
    int? NumVariants
);

public record PsProductVariant(
    Guid Id,
    string? SystemName,
    string? ProductName,
    string? Key,
    PsProductType? Type,
    PsRule? Rule,
    ImmutableArray<string>? PrimaryCodes,
    ImmutableArray<PsUpstreamItem>? UpstreamItems
);
